import{_ as l,a0 as n,w as p,s,ao as o,I as d,x as a,a1 as r,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"使用 RT-Thread 實時操作系統驅動你的硬件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 RT-Thread 實時操作系統驅動你的硬件 | LCTT (202008) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 RT-Thread 實時操作系統驅動你的硬件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 RT-Thread 實時操作系統驅動你的硬件 | LCTT (202008) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202008/20200603 Code your hardware using this open source RTOS","title":"使用 RT-Thread 實時操作系統驅動你的硬件","tag":"202008","desc":""},"relativePath":"202008/20200603 Code your hardware using this open source RTOS.md","filePath":"[post].md"}'),h={name:"202008/20200603 Code your hardware using this open source RTOS.md"};function T(u,e,m,f,b,C){const t=n("Link");return p(),s("div",null,[e[26]||(e[26]=o('<h1 id="使用-rt-thread-實時操作系統驅動你的硬件" tabindex="-1">使用 RT-Thread 實時操作系統驅動你的硬件 <a class="header-anchor" href="#使用-rt-thread-實時操作系統驅動你的硬件" aria-label="Permalink to “使用 RT-Thread 實時操作系統驅動你的硬件”">​</a></h1><blockquote><p>編程驅動一個微處理器芯片是相當有難度的，但在嵌入式系統開發上，實時操作系統可以為你解決很多此類的困難。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202008/15/065451hu3784opp7p74qtp.jpg" alt=""></p><p>從通用計算的角度，操作系統是提供計算機基本功能的一組軟件。操作系統保證了計算機硬件可以探測並響應外圍器件（如鍵盤、屏幕、移動設備、打印機等），並管理內存空間和外部存儲空間。</p><p>雖然一個 CPU 核心同一時間只能運行單個線程，但現代操作系統可以使多個程序表現的像是在同時運行。每一個任務執行的如此之短，一系列任務切換的如此之快，以至於看起來多個任務像是在並行進行。這一切都是由一個叫做 <em>調度器</em> 的子進程來控制的。</p><p>操作系統通常是為計算機準備的，安裝在硬盤上，管理計算機所要執行的任務。</p><h3 id="為什麼實時操作系統對嵌入式系統而言不可或缺" tabindex="-1">為什麼實時操作系統對嵌入式系統而言不可或缺 <a class="header-anchor" href="#為什麼實時操作系統對嵌入式系統而言不可或缺" aria-label="Permalink to “為什麼實時操作系統對嵌入式系統而言不可或缺”">​</a></h3>',7)),d("p",null,[e[1]||(e[1]=a("我曾經在 2008 年接觸過嵌入式軟件，那時候我還是一名學生，正在學習 ",-1)),r(t,{href:"https://en.wikipedia.org/wiki/Intel_MCS-51"},{default:i(()=>[...e[0]||(e[0]=[a("MCS-51",-1)])]),_:1}),e[2]||(e[2]=a(" 微處理器編程。因為我的主修專業是計算機科學，我在其它課程中的所有程序都是在 PC 上執行的。為微處理器芯片編程是完全不同的體驗。人生中第一次，我看到我的程序在裸板上運行，即使到現在我仍然記得，在我看到自己人生中第一個走馬燈程序成功運行時的那種興奮和激動。",-1))]),e[27]||(e[27]=o('<p>但那種興奮轉瞬即逝。隨着為裸板寫出越來越多的程序，我遇到了越來越多的問題。這種沮喪並不是我獨有的。直接為芯片寫程序很困難，這也是 PC 要運行操作系統的很重要的原因。不幸的是，微處理器芯片（或嵌入式系統）通常是沒有操作系統的，它們只能採用“硬編碼”的方式編程，沒有操作系統幫助你管理代碼的運行。</p><p>在以“硬編碼”的方式為處理芯片編寫代碼的時候，可能會遇到下列問題：</p><h4 id="併發" tabindex="-1">併發 <a class="header-anchor" href="#併發" aria-label="Permalink to “併發”">​</a></h4><p>在裸板上是沒有管理程序運行的現成守護進程的。嵌入式系統軟件中，無可避免的要把所有的邏輯功能放在一個巨大的 <code>while (1)</code> 循環中。每個功能可能包含一個或多個延時函數。CPU 在運行延時函數的時候是順序執行的，沒有任何辦法跨越一個不必要的延時。正因如此，運行事務的復位操作只能是等待。最終結果就是很多的 CPU 處理時間浪費在空循環上，這對任務的併發非常不利。</p><h4 id="模組化" tabindex="-1">模組化 <a class="header-anchor" href="#模組化" aria-label="Permalink to “模組化”">​</a></h4><p>從軟件工程的角度，高內聚低耦合原則在軟件開發過程中被不厭其煩的頻頻強調，但是嵌入式軟件的不同模組之間常常是重度耦合的，很多功能都集中在一個巨大的 <code>while (1)</code> 循環中，很難切分為模組。設計低耦合軟件在編程上只是繁瑣一些，但在嵌入式系統上，要低耦合就難以編寫比較大型的軟件。</p><p>與此同時，如果使用了看門狗定時器，程序員還得在調用延時函數時倍加小心。如果延時時間太長，主程序沒有得到及時“餵狗”的時機，那麼看門狗將在程序運行過程中被觸發。嵌入式系統軟件開發過程中，需要考慮的東西太多了，即便是個簡單的延時函數，都不能掉以輕心。軟件越複雜，就越需要細心。想像一下，試圖將這一系列具有精細時間關係的交互功能拆分為模組會怎麼樣。</p><h4 id="軟件生態" tabindex="-1">軟件生態 <a class="header-anchor" href="#軟件生態" aria-label="Permalink to “軟件生態”">​</a></h4>',8)),d("p",null,[e[4]||(e[4]=a("很多高級的軟件組件依賴於其所基於的底層操作系統的實現。舉個自身的例子，我曾開發過一個基於 ",-1)),r(t,{href:"https://www.embedded-solutions.at/files/freemodbus-v1.6-apidoc/"},{default:i(()=>[...e[3]||(e[3]=[a("FreeModbus",-1)])]),_:1}),e[5]||(e[5]=a(" 的開源項目，原計劃將它移植到多種平台上，包括裸板。但與適應不同操作系統的便利性相比，有些功能過於複雜，無法在所有裸機板上實現。更糟糕的是，很多硬件平台因為缺乏一致性，只能各自從頭做起。",-1))]),e[28]||(e[28]=o('<p>直至現在，我的 Modbus 棧仍然不支持在裸板上運行。</p><p>很多像 Realtek、TI 和 MediaTek 的大廠，所提供的 WiFi 軟件開發工具只能在操作系統上運行，且他們不公開固件源碼，所以在裸板上根本沒法使用這些工具。</p><h4 id="實時性" tabindex="-1">實時性 <a class="header-anchor" href="#實時性" aria-label="Permalink to “實時性”">​</a></h4><p>有些應用領域對實時性有要求，比如有些場景中，必須在特定的時間觸發特定的軟件操作。在工業控制場景，機器實體控制過程中，機械部件必須以確定的時間和確定的順序執行動作。如果不能保證控制系統的實時性，整個機器可能出現功能異常，甚至危及工人生命。在裸板平台，所有的功能都塞在一個巨大的 <code>while (1)</code> 循環中，實時性無從保證。</p><h4 id="重用性" tabindex="-1">重用性 <a class="header-anchor" href="#重用性" aria-label="Permalink to “重用性”">​</a></h4><p>重用性依賴於模組化。沒誰願意翻來覆去做一成不變的事，對程序員而言更是如此。這不單單是浪費時間，更要命的是這使得代碼的維護異常複雜。尤其是，因為功能的實現依賴於底層的硬件，使用了不同芯片的不同硬件平台上，同樣的功能必須適配不同的硬件平台。這種情況下，重新發明輪子是無法避免的。</p><h3 id="實時操作系統的優勢" tabindex="-1">實時操作系統的優勢 <a class="header-anchor" href="#實時操作系統的優勢" aria-label="Permalink to “實時操作系統的優勢”">​</a></h3><p>幸運的是，現在有針對各種微處理器芯片的操作系統，它們被稱為實時操作系統（RTOS），和大多數操作系統一樣，它們擁有調度器，保證代碼以可預見的順序運行。</p>',8)),d("p",null,[e[8]||(e[8]=a("我是在 2010 年初次在裸板上使用實時操作系統。那時候，",-1)),r(t,{href:"https://en.wikipedia.org/wiki/STM32"},{default:i(()=>[...e[6]||(e[6]=[a("STM32",-1)])]),_:1}),e[9]||(e[9]=a(" 系列微處理器（MCU）開始流行，因為這種微處理器性能強大、功能豐富，很多人在上面跑操作系統。我使用的是 ",-1)),r(t,{href:"https://github.com/RT-Thread/rt-thread"},{default:i(()=>[...e[7]||(e[7]=[a("RT-Thread",-1)])]),_:1}),e[10]||(e[10]=a(" 操作系統，有很多基於它的現成組件可用。它使用的是 Apache 2.0 許可，和其它操作系統相比，我覺得這個很舒心。我已經基於它作為平台從事開發工作 10 年了。",-1))]),e[29]||(e[29]=o('<p>使用實時操作系統為裸板編程，操作系統為我們解決了需要處理的大部分問題。</p><h4 id="模組化-1" tabindex="-1">模組化 <a class="header-anchor" href="#模組化-1" aria-label="Permalink to “模組化”">​</a></h4><p>在操作系統支持下，整個軟件可以分割為多個任務（即線程）。每個線程擁有自己獨立的運行空間。線程之間互相獨立，這促進了軟件的模組化。</p><h4 id="併發-1" tabindex="-1">併發 <a class="header-anchor" href="#併發-1" aria-label="Permalink to “併發”">​</a></h4><p>如果一個線程有延時函數，它將自動讓出 CPU 資源給需要 CPU 的線程，這提高了 CPU 的整體利用率，也提升了系統的併發性能。</p><h4 id="實時性-1" tabindex="-1">實時性 <a class="header-anchor" href="#實時性-1" aria-label="Permalink to “實時性”">​</a></h4><p>實時操作系統從設計上就具備實時性。每個線程都被指定了特定的優先級，比較重要的線程設置為更高的優先級，不重要的線程優先級也低。正是以這種方式，軟件整體的實時性得到了保證。</p><h4 id="開發效率" tabindex="-1">開發效率 <a class="header-anchor" href="#開發效率" aria-label="Permalink to “開發效率”">​</a></h4><p>操作系統提供了統一的抽象接口，這使得可重用組件得以不斷積累，同時提升了開發效率。</p><p>操作系統是軟件極客集體智慧的結晶。很多通用的軟件功能，如信號量、事件提醒、郵箱、環形緩衝、單向鏈表、雙向鏈表等，被抽象出來並實現了封裝，可隨時調用。</p><p>Linux、RT-Thread 等操作系統為五花八門的硬件實現了一致的硬件接口，也就是常説的設備驅動框架。正因如此，軟件工程師可以專注於軟件開發，而不用關心底層的硬件，也不用重複造輪子。</p><h4 id="軟件生態-1" tabindex="-1">軟件生態 <a class="header-anchor" href="#軟件生態-1" aria-label="Permalink to “軟件生態”">​</a></h4><p>RT-Thread 豐富的軟件生態為大量的從業者帶來了巨大的改變。操作系統帶來的模組化和重用性，使得程序員可以基於 RT-Thread 封裝出方便嵌入式系統開發使用的可重用組件。這些組件可以在其它項目中重用，也可以分享給其他的嵌入式應用開發者，以最大化軟件的價值。</p><p>比如，LkdGui 是個開源的單色顯示圖形庫，你可能在工業控制面板上簡單而美觀的設置界面上見過它。LkdGui 提供了像描點、畫線、繪矩形及顯示文本、按鈕組件、進度條等繪圖功能。</p><p><img src="https://opensource.com/sites/default/files/uploads/lkdgui.jpg" alt="LkdGui" title="LkdGui"></p><p>使用像 LkdGui 這樣兼具擴展性和健壯性的功能庫，程序員們可以在同行已有工作成果的基礎上充分施展自己的才能。而這一切，沒有實時操作系統這樣一個統一的基礎，是根本不可能的。</p><h3 id="試用-rt-thread" tabindex="-1">試用 RT-Thread <a class="header-anchor" href="#試用-rt-thread" aria-label="Permalink to “試用 RT-Thread”">​</a></h3><p>作為開源極客，我已經在 GitHub 上開源了一些嵌入式軟件。在發佈開源軟件之前，我很少對他人談及自己曾經的項目，因為不同的人在使用各種不同的微處理器芯片和硬件平台，我的代碼極可能無法在他人的板子上運行。類似於 RT-Thread 這樣的實時操作系統極大的提升了軟件的可重用性，所以全世界的不同領域的專家得以就同一個項目展開探討。這鼓勵着越來越多的人分享和交流各自的項目。如果你在做裸板的軟件開發，下次可以試試 TR-Thread。</p><hr>',19)),d("p",null,[e[12]||(e[12]=a("via: ",-1)),r(t,{href:"https://opensource.com/article/20/6/open-source-rtos"},{default:i(()=>[...e[11]||(e[11]=[a("https://opensource.com/article/20/6/open-source-rtos",-1)])]),_:1})]),d("p",null,[e[17]||(e[17]=a("作者：",-1)),r(t,{href:"https://opensource.com/users/zhu-tianlong"},{default:i(()=>[...e[13]||(e[13]=[a("Zhu Tianlong",-1)])]),_:1}),e[18]||(e[18]=a(" 選題：",-1)),r(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[14]||(e[14]=[a("lujun9972",-1)])]),_:1}),e[19]||(e[19]=a(" 譯者：",-1)),r(t,{href:"https://github.com/silentdawn-zz"},{default:i(()=>[...e[15]||(e[15]=[a("silentdawn-zz",-1)])]),_:1}),e[20]||(e[20]=a(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[16]||(e[16]=[a("wxy",-1)])]),_:1})]),d("p",null,[e[23]||(e[23]=a("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[21]||(e[21]=[a("LCTT",-1)])]),_:1}),e[24]||(e[24]=a(" 原創編譯，",-1)),r(t,{href:"https://linux.cn/"},{default:i(()=>[...e[22]||(e[22]=[a("Linux中國",-1)])]),_:1}),e[25]||(e[25]=a(" 榮譽推出",-1))])])}const R=l(h,[["render",T]]);export{x as __pageData,R as default};
